function safePublic(v){if(!v||typeof v!=='object')return v;if(Array.isArray(v))return v.map(safePublic);let out={...v};if(out.status==='running'&&Date.now()-Date.parse(out.startedAt)>180000){out.status='interrupted';out.error='Resultado não confirmado após o prazo. Pode ter ocorrido interrupção da conexão. Não repetimos a chamada para evitar cobrança duplicada.'}if(out.chunks)out.chunks=out.chunks.map(safePublic);if(out.quarantined)out.quarantined=out.quarantined.map(r=>({...r,title:'Ato retido para revisão de evidência'}));if(out.records){out.records=out.records.map(r=>r.id==='ai-1-1'?{...r,editorial:'O valor é expressivo, mas crédito orçamentário não equivale a gasto executado. O Anexo II identifica a dedução em Transferências Especiais à União, sob supervisão da Secretaria da Fazenda. Cabe apurar a motivação e a execução efetiva, sem afirmar ausência desses dados no ato.'}:r);let sensitive=r=>/(tratamento de sa[uú]de|licen[cç]a.{0,140}(m[eé]dic|sa[uú]de|doen[cç]a)|afastamento.{0,140}(doen[cç]a|m[eé]dic)|aux[ií]lio.doen[cç]a|\bCID[- :])/i.test(JSON.stringify(r));let removed=out.records.filter(sensitive);out.records=out.records.filter(r=>!sensitive(r));out.privacyWithheld=removed.length;if(removed.length){out.complete=false;out.limitations=(out.limitations||'')+' '+removed.length+' atos com informações pessoais de saúde foram omitidos desta visualização pública.'}}return out}
